  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C36"],
      "claim": "MK-458, a propylamine-containing heterocycle, had an absolute oral bioavailability of approximately 5% in Parkinson's patients, supporting low F for the query's propylamine/heterocycle motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "3-PPP, a propylpiperidine phenol, failed clinically due to low oral bioavailability in humans, supporting low F for the query's propylamine/phenol-like polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Compound 26, a propylmorpholine phenol, was predicted to have 0% oral bioavailability in humans, supporting low F for the query's propylamine/heterocycle scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Milnacipran has high absolute oral bioavailability (85±3%) in humans, but its small non-quaternary cyclopropane amide structure is too distant from the large quaternary ammonium query to transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C35"],
      "claim": "Levoprotiline has 40% absolute oral bioavailability in healthy volunteers, above the threshold, but it is a secondary-amine tetracyclic without the query's permanent quaternary charge, so transferability is low.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low oral bioavailability (<20%). The query is a large, rigid quaternary ammonium alkaloid with multiple hydroxyls; its permanent positive charge and high polarity are expected to severely limit membrane permeation. Low-F analogues sharing propylamine/heterocycle motifs (MK-458 ~5%, 3-PPP low, compound 26 0%) support this direction, while high-F analogues are structurally distant and do not transfer.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "All retrieved analogues have low Morgan similarity (<0.20), limiting structural transferability.",
    "No quaternary ammonium analogue with measured absolute oral bioavailability was retrieved."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

